  'help.faq.cantLogin.q': 'Jeg kan ikke logge inn på kontoen min',
  'help.faq.cantLogin.a': 'Sjekk at du bruker riktig e-post og passord. Hvis du har glemt passordet ditt, klikk "Glemt passord?" på innloggingsskjermen. Hvis problemet vedvarer, opprett en supportbillett.',
  'help.faq.notReceiving.q': 'Jeg mottar ikke e-poster',
  'help.faq.notReceiving.a': 'Sjekk Spam-mappen din først. Sørg for at lagringen din ikke er full. Hvis problemet fortsetter, bekreft at avsenderen har riktig e-postadresse og opprett en supportbillett.',
  'help.faq.cantSend.q': 'Jeg kan ikke sende e-poster',
  'help.faq.cantSend.a': 'Bekreft internettforbindelsen din og at mottakerens e-postadresse er korrekt. Sjekk om du har vedlegg som er for store (maks 25MB). Prøv igjen om noen minutter.',
  'help.faq.forgotPassword.q': 'Jeg har glemt passordet mitt',
  'help.faq.forgotPassword.a': 'På innloggingsskjermen, klikk "Glemt passord?" og følg instruksjonene for å tilbakestille passordet ditt via din gjenopprettings-e-postadresse.',
  'help.faq.accountSecurity.q': 'Jeg tror kontoen min har blitt kompromittert',
  'help.faq.accountSecurity.a': 'Endre passordet ditt umiddelbart. Sjekk Sendt-mappen for meldinger du ikke har sendt. Aktiver to-faktor autentisering i Innstillinger > Sikkerhet. Hvis nødvendig, opprett en hastesupportbillett.',
  'help.faq.appAccess.q': 'Hvordan får jeg tilgang til appen på mobil?',
  'help.faq.appAccess.a': 'Du kan få tilgang til Chatyy via hvilken som helst mobilnettleser på chatyy.com.br, eller laste ned appen vår fra appbutikken på enheten din.',

  // Privacy modal
  'privacy.title': 'Personvernerklæring',
  'privacy.subtitle': 'Hvordan vi beskytter og håndterer dataene dine',
  'privacy.lastUpdated': 'Sist oppdatert: Mars 2026',
  'privacy.dataCollection.title': 'Datainnsamling',
  'privacy.dataCollection.body': 'Vi samler kun inn informasjon som er nødvendig for å tilby vår e-posttjeneste: navnet ditt, e-postadressen din, og innholdet i meldingene du sender og mottar. Vi selger eller deler ikke dine personopplysninger med tredjeparter for markedsføringsformål.',
  'privacy.dataUsage.title': 'Hvordan vi bruker dataene dine',
  'privacy.dataUsage.body': 'Dataene dine brukes utelukkende for å drifte og forbedre e-posttjenesten, inkludert levering av meldinger, filtrering av spam, tilby AI-drevne funksjoner (med ditt samtykke), og opprettholde kontosikkerhet.',
  'privacy.dataSecurity.title': 'Datasikkerhet',
  'privacy.dataSecurity.body': 'Vi bruker bransjestandard kryptering (TLS/SSL) for all data i transitt og i ro. Økter beskyttes med krypterte tokens og CSRF-beskyttelse. Vi reviderer jevnlig våre sikkerhetsrutiner.',
  'privacy.cookies.title': 'Informasjonskapsler & Lokal lagring',
  'privacy.cookies.body': 'Vi bruker essensielle informasjonskapsler og lokal lagring for å opprettholde økten din, huske preferansene dine (tema, språk), og gi en sømløs opplevelse. Vi bruker ikke sporingskapsler fra tredjeparter.',
  'privacy.thirdParties.title': 'Tredjepartstjenester',
  'privacy.thirdParties.body': 'Vi kan bruke tredjepartstjenester for spesifikke funksjoner som AI-funksjoner (Anthropic Claude) og push-varsler. Disse tjenestene er bundet av sine egne personvernerklæringer og behandler kun minimumsdata som kreves.',
  'privacy.rights.title': 'Dine rettigheter',
  'privacy.rights.body': 'Du har rett til å få tilgang til, korrigere, eksportere eller slette dine personopplysninger når som helst. Du kan administrere dataene dine gjennom Innstillinger eller ved å kontakte supportteamet vårt.',
  'privacy.contact.title': 'Kontakt oss',
  'privacy.contact.body': 'For spørsmål relatert til personvern eller databehandling, kontakt oss på privacy@chatyy.com.br. Vi vil svare innen 30 dager.',

  // Terms modal
  'terms.title': 'Vilkår for tjenesten',
  'terms.subtitle': 'Retningslinjer for bruk av Chatyy',
  'terms.lastUpdated': 'Sist oppdatert: Mars 2026',
  'terms.acceptance.title': 'Aksept av vilkår',
  'terms.acceptance.body': 'Ved å få tilgang til eller bruke Chatyy, godtar du å være bundet av disse vilkårene for tjenesten. Hvis du ikke er enig i noen del av disse vilkårene, kan du ikke bruke tjenesten.',
  'terms.services.title': 'Beskrivelse av tjenester',
  'terms.services.body': 'Chatyy tilbyr e-postkommunikasjonstjenester inkludert sending, mottak og administrering av e-poster, sammen med AI-drevne funksjoner, kalenderintegrasjon og videokonferansekapabiliteter.',
  'terms.accounts.title': 'Brukerkontoer',
  'terms.accounts.body': 'Du er ansvarlig for å opprettholde sikkerheten til kontoen din. Du må ikke dele passordet ditt eller tillate uautorisert tilgang til kontoen din. Du må være minst 13 år gammel for å bruke denne tjenesten.',
  'terms.conduct.title': 'Akseptabel bruk',
  'terms.conduct.body': 'Du godtar å ikke bruke tjenesten til å sende spam, malware, phishing eller annet ulovlig innhold. Du må ikke forsøke å få tilgang til andre brukeres kontoer eller forstyrre tjenesteinfrastrukturen.',
  'terms.content.title': 'Innholdsrettigheter',
  'terms.content.body': 'Du beholder eierskapet til alt innhold du oppretter og sender gjennom tjenesten. Vi gjør ikke krav på eierskap over e-postene eller vedleggene dine. Vi kan prosessere innhold etter behov for å tilby tjenesten.',
  'terms.limitation.title': 'Ansvarsbegrensning',
  'terms.limitation.body': 'Chatyy tilbys "som den er". Vi streber etter 99,9% oppetid, men garanterer ikke uavbrutt tjeneste. Vi er ikke ansvarlige for indirekte, tilfeldige eller følgeskader som oppstår fra din bruk av tjenesten.',
  'terms.termination.title': 'Kontooppsigelse',
  'terms.termination.body': 'Vi kan suspendere eller avslutte kontoer som bryter med disse vilkårene. Du kan slette kontoen din når som helst gjennom Innstillinger. Ved oppsigelse vil dataene dine bli slettet innen 30 dager.',
  'terms.changes.title': 'Endringer i vilkår',
  'terms.changes.body': 'Vi kan oppdatere disse vilkårene fra tid til annen. Vi vil varsle deg om betydelige endringer via e-post eller i-app varsling. Fortsatt bruk av tjenesten etter endringer utgjør aksept av de oppdaterte vilkårene.',

